<?php
namespace EventFlow\Presentation\Api;
final readonly class ImportAdministrationRouteRegistrar implements RestRouteRegistrar
{public function __construct(private ImportAdministrationController$admin,private ImportUploadController$uploads){}public function register(RestRouteRegistry$routes):void{$collection='/events/(?P<event_id>\d+)/imports';$resource=$collection.'/(?P<import_job_id>\d+)';$routes->registerAuthenticatedGet(SystemRouteRegistrar::NAMESPACE,$collection,$this->admin->list(...));$routes->registerAuthenticatedPost(SystemRouteRegistrar::NAMESPACE,$collection,$this->uploads->create(...));$routes->registerAuthenticatedGet(SystemRouteRegistrar::NAMESPACE,$resource,$this->admin->read(...));$routes->registerAuthenticatedPost(SystemRouteRegistrar::NAMESPACE,$resource.'/parse',$this->admin->parse(...));$routes->registerAuthenticatedPost(SystemRouteRegistrar::NAMESPACE,$resource.'/dry-run',$this->admin->dryRun(...));$routes->registerAuthenticatedPost(SystemRouteRegistrar::NAMESPACE,$resource.'/apply',$this->admin->apply(...));$routes->registerAuthenticatedPost(SystemRouteRegistrar::NAMESPACE,$resource.'/cancel',$this->admin->cancel(...));$routes->registerAuthenticatedGet(SystemRouteRegistrar::NAMESPACE,$resource.'/rows',$this->admin->rows(...));$routes->registerAuthenticatedGet(SystemRouteRegistrar::NAMESPACE,$resource.'/result',$this->admin->result(...));}}
